CREATE OR REPLACE FUNCTION ml_setting.block_frozen_set() RETURNS TRIGGER AS $body$
BEGIN
    IF NOT OLD.frozen THEN
        IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'parameter set %/%@% is frozen (used by a registered model) and can not be deleted', OLD.family, OLD.name, OLD.version;
    END IF;
    IF NEW.content IS DISTINCT FROM OLD.content OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
       OR NEW.family IS DISTINCT FROM OLD.family OR NEW.name IS DISTINCT FROM OLD.name
       OR NEW.version IS DISTINCT FROM OLD.version OR NEW.category IS DISTINCT FROM OLD.category
       OR NOT NEW.frozen THEN
        RAISE EXCEPTION 'parameter set %/%@% is frozen (used by a registered model) - save the change as a new version', OLD.family, OLD.name, OLD.version;
    END IF;
    RETURN NEW;
END;
$body$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION ml_setting.block_frozen_rows() RETURNS TRIGGER AS $body$
BEGIN
    IF EXISTS (SELECT 1 FROM ml_setting.parameter_set WHERE id = OLD.set_id AND frozen) THEN
        RAISE EXCEPTION 'the rows of parameter set % are frozen (used by a registered model) - save the change as a new version', OLD.set_id;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$body$ LANGUAGE plpgsql;
